def _json_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _parse_replication_pairs(query: Mapping[str, list[str]]) -> list[tuple[str, str, str]]:
    """Parse repeatable persisted packet pair references shared by release routes."""

    raw_pairs = query.get("pair", [])
    if not raw_pairs:
        raise ValueError("at least one pair=PAIR_ID=LEFT=RIGHT query value is required")
    pairs = []
    for raw_pair in raw_pairs:
        parts = raw_pair.split("=", 2)
        if len(parts) != 3 or not all(parts):
            raise ValueError("pair values must use PAIR_ID=LEFT=RIGHT")
        pairs.append((parts[0], parts[1], parts[2]))
    return pairs


def _parse_review_decisions(
    query: Mapping[str, list[str]], prefix: str = ""
) -> tuple[dict[str, Any], ...]:
    """Parse compact review decision query values without introducing identity fields."""

    raw_decisions = query.get(f"{prefix}decision", [])
    entry_ids = query.get(f"{prefix}entry_id", [])
    rationales = query.get(f"{prefix}rationale", [])
    action_values = query.get(f"{prefix}required_action", [])
    actions: dict[str, list[str]] = {}
    for raw_action in action_values:
        parts = raw_action.split("=", 1)
        if len(parts) == 2 and all(parts):
            actions.setdefault(parts[0], []).append(parts[1])
        elif raw_action:
            action_key = entry_ids[-1] if entry_ids else "review-0"
            actions.setdefault(action_key, []).append(raw_action)
    decisions: list[dict[str, Any]] = []
    for index, raw_decision in enumerate(raw_decisions):
        parts = raw_decision.split("=", 2)
        if len(parts) == 3 and all(parts):
            entry_id, decision, rationale = parts
        elif len(parts) == 2 and all(parts):
            entry_id, decision = parts
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        elif len(parts) == 1 and parts[0]:
            entry_id = entry_ids[index] if index < len(entry_ids) else f"{prefix or 'review-'}{index}"
            decision = parts[0]
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        else:
            raise ValueError("decision values must use ENTRY_ID=DECISION=RATIONALE or DECISION")
        decisions.append(
            {
                "entry_id": entry_id,
                "decision": decision,
                "rationale": rationale,
                "required_actions": tuple(actions.get(entry_id, ())),
            }
        )
    return tuple(decisions)


class ApiHandler(BaseHTTPRequestHandler):
    """Small API handler with explicit endpoints and bounded error bodies."""

    server_version = "glio-noncode/0.1"
    runtime_factory: Callable[[], CaseRuntime] | None = None

    def _runtime(self) -> CaseRuntime:
        factory = self.runtime_factory or (lambda: CaseRuntime())
        runtime = getattr(self.server, "glio_runtime", None)
        if runtime is None:
            runtime = factory()
            setattr(self.server, "glio_runtime", runtime)  # noqa: B010 - the HTTP server is intentionally extended
        return runtime

    def _module_certification_context(
        self, *, include_certification: bool = True
    ) -> tuple[Any, Any, Any, Any, Any]:
        """Cache the immutable repository aggregate for related read routes."""

        context = getattr(self.server, "glio_module_certification_context", None)
        if context is None:
            inventory = build_module_inventory()
            matrix = build_module_certification(inventory)
            plan = build_module_certification_task_plan(matrix) if include_certification else None
            gate = evaluate_module_certification_gate(matrix, plan) if plan is not None else None
            runtime = run_module_certification(inventory=inventory) if include_certification else None
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
        elif include_certification and context[2] is None:
            inventory, matrix, _, _, _ = context
            plan = build_module_certification_task_plan(matrix)
            gate = evaluate_module_certification_gate(matrix, plan)
            runtime = run_module_certification(inventory=inventory)
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
        return context

    def _deployment_guard(self) -> DeploymentGuard:
        guard = getattr(self.server, "glio_deployment_guard", None)
        if guard is None:
            guard = DeploymentGuard(default_deployment_profile("127.0.0.1"))
            setattr(self.server, "glio_deployment_guard", guard)  # noqa: B010 - server-local policy attachment
        return guard

    def _authorize_request(self) -> bool:
        """Apply the deployment profile before dispatching any API route."""

        authorization = self.headers.get("Authorization", "")
        token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else None
        decision = self._deployment_guard().authorize(
            self.command,
            urlsplit(self.path).path,
            token=token,
        )
        if decision.allowed:
            return True
        status = HTTPStatus.UNAUTHORIZED if decision.reason == "missing_or_invalid_credential" else HTTPStatus.FORBIDDEN
        self._write(
            status,
            {
                "error": "authentication_required" if status is HTTPStatus.UNAUTHORIZED else "forbidden",
                "message": decision.reason,
                "operation": decision.operation.value,
                "audit_sequence": decision.audit_sequence,
            },
            headers={"WWW-Authenticate": "Bearer"} if status is HTTPStatus.UNAUTHORIZED else None,
        )
        return False

